export function RecordDetail({resource,row:initial,onClose,onChanged,initialTab}:{resource:Resource;row:Row;initialTab?:string;onClose:()=>void;onChanged:(row:Row)=>void}){const {t,label,resources,notify,refreshKey,me,navigate}=useApp();const [row,setRow]=useState(initial);const [assigning,setAssigning]=useState(false);const [linked,setLinked]=useState<{resource:Resource;row:Row}|null>(null);const [tab,setTab]=useState(initialTab==='signatures'&&(resource.signatureActions?.length||supportsSignatureRequests(resource))?'signatures':initialTab==='workflow'?'workflow':'details');const [editing,setEditing]=useState(false);const [action,setAction]=useState<string|null>(null);const [activity,setActivity]=useState<Row[]>([]);const [attachments,setAttachments]=useState<Row[]>([]);const [uploading,setUploading]=useState(false);const [error,setError]=useState('');const [revision,setRevision]=useState(0);
 useEffect(()=>{api<Row & {record?:Row;activity?:Row[];attachments?:Row[];_timeline?:Row[];_attachments?:Row[]}>(`/api/data/${resource.key}/${initial.id}`).then(data=>{setRow(data.record||data);setError('');setActivity(data._timeline||data.activity||[]);setAttachments(data._attachments||data.attachments||[]);}).catch(e=>setError(errorMessage(e,t)));},[initial.id,revision,refreshKey]);
 const canDelegate=resources.delegations?.fields.find(field=>field.key==='target_resource')?.options?.includes(resource.key)&&me.roles.some(role=>role!=='external');const childResources=Object.values(resources).filter(r=>r.key!==resource.key&&(r.parent===resource.key||r.fields.some(f=>f.ref===resource.key)));const changed=(next:Row)=>{setRow(next);setRevision(v=>v+1);onChanged(next);};const upload=async(file:File)=>{setUploading(true);try{const form=new FormData();form.set('resource',resource.key);form.set('record_id',row.id);form.set('file',file);await api('/api/attachments',{method:'POST',body:form});notify(t('success'));setRevision(v=>v+1);}catch(e){setError(errorMessage(e,t));}finally{setUploading(false);}};
 return <Modal wide title={String(row[resource.titleField]||label(resource))} onClose={onClose} footer={<><span className="detail-id">{t('version')} {String(row.version)} · {row.id.slice(0,8)}</span><Button icon={Printer} onClick={()=>{window.location.assign("/api/print?resource="+encodeURIComponent(resource.key)+"&id="+encodeURIComponent(row.id));}}>{t('print')}</Button>{!resource.parent&&!resource.hidden&&resource.module!=='settings'&&<Button onClick={()=>{onClose();navigate('/archives?'+new URLSearchParams({resource:resource.key,view:row.archived?'archived':'active',q:String(row[resource.titleField]||'')}));}}>{t('archives')}</Button>}<CloudExportButton resource={resource.key} recordId={row.id} title={String(row[resource.titleField]||'')}/><WorkspaceServicesButton preset={{resource:resource.key,record_id:row.id,provider:['meetings','events'].includes(resource.key)?'calendar':['contacts','engagements'].includes(resource.key)?'gmail':'docs'}}/>{!resource.readonly&&resource.capabilities?.edit!==false&&(resource.key!=='journal_entries'||row.status==='draft'&&!row.source_resource&&!row.reversal_of)&&(resource.key!=='delegations'||row.requester_id===me.user.id&&['assigned','needs_changes'].includes(String(row.status)))&&<Button onClick={()=>setEditing(true)}>{t('edit')}</Button>}</>}><div className="detail-summary"><div>{row.status?<Badge value={row.status}/>:<Badge value={row.archived?'archived':'active'}/>}<span className="muted">{label(resource)}</span></div>{row.status==='posted'&&<p className="info-note">{t('immutableNotice')}</p>}</div><div className="tabs">{['details',...(resource.actions?.length?['workflow']:[]),...(supportsOrganization(resource)?['recordOrganization']:[]),'related','attachments','activity',...(resource.signatureActions?.length||supportsSignatureRequests(resource)?['signatures']:[])].map(key=><button key={key} className={tab===key?'active':''} onClick={()=>setTab(key)}>{t(key)}{key==='attachments'&&attachments.length>0&&<span>{attachments.length}</span>}</button>)}</div>{error&&<ErrorBanner message={error} onRetry={()=>setRevision(v=>v+1)}/>}
 {['details','workflow'].includes(tab)&&<ConfirmationNotesPanel row={row}/>} {['details','workflow'].includes(tab)&&resource.key==='tasks'&&<TaskCompletionPanel key={row.id+':'+row.version} row={row} onSaved={changed}/>} {tab==='details'&&<>{resource.key==='audience_groups'&&<MailAssetTools resource={resource.key} row={row}/>}{resource.key==='delegations'&&<DelegationStatus row={row}/>}<WorkTargetLink row={row}/><dl className="detail-fields">{resource.fields.filter(field=>!['target_resource','target_id','completion_required','completion_user_ids'].includes(field.key)&&(!resource.privacy_supported||!['visibility','viewer_user_ids','viewer_team_ids','is_private'].includes(field.key))).map(field=><div key={field.key} className={['textarea','json'].includes(field.type)?'full-field':''}><dt>{label(configurationField(resource.key,field))}</dt><dd>{field.ref&&resources[field.ref]&&row[field.key]?<button className="reference-link" onClick={()=>{api<Row>('/api/data/'+field.ref+'/'+String(row[field.key])).then(record=>setLinked({resource:resources[field.ref!],row:record})).catch(e=>notify(errorMessage(e,t),'error'));}}><ConfigurationValue resourceKey={resource.key} field={field} value={row[field.key]} row={row}/></button>:<ConfigurationValue resourceKey={resource.key} field={field} value={row[field.key]} row={row}/>}</dd></div>)}</dl>{resource.privacy_supported&&<TaskVisibilityPanel key={row.id+':'+row.version} resource={resource} row={row} onSaved={changed}/>} {canDelegate&&<div className="action-wrap"><Button onClick={()=>setAssigning(true)}>{t('delegationCreate')}</Button></div>}</>}
 {['details','workflow'].includes(tab)&&<><FinanceRecordSummary resource={resource.key} row={row}/>{resource.key==='journal_entries'&&<JournalLinesSummary row={row}/>}{resource.actions&&resource.actions.length>0&&<section className="workflow-section"><h3>{t('workflow')}</h3><div className="action-wrap">{resource.actions.filter(a=>a!=='confirm_completion'&&(resource.key!=='tasks'||!row.completion_required||!['complete','submit_review'].includes(a))).filter(a=>resource.key!=='delegations'||delegationActionVisible(a,row,me)).filter(a=>resource.key!=='journal_entries'||a==='post'&&row.status==='draft'||a==='reverse'&&row.status==='posted').filter(a=>a!=='restore'||row.archived).filter(a=>a!=='archive'||!row.archived).map(a=><Button key={a} onClick={()=>setAction(a)} variant={['submit','approve','accept','complete','confirm','post'].includes(a)?'soft':''}>{t(resource.key==='delegations'&&a==='revoke'?'delegationRevoke':a)}</Button>)}</div></section>}</>}
 {tab==='recordOrganization'&&<RecordOrganization resource={resource} row={row} onSaved={changed}/>}
 {tab==='related'&&<div className="related-sections"><LinkedWorkspaceItems resource={resource.key} recordId={row.id}/>{Array.isArray(row._context)&&<ContextRecords groups={row._context as {resource:string;rows:Row[];total:number}[]}/>} {childResources.length?childResources.map(child=>child.key==='journal_lines'?<JournalLinesSummary key={child.key} row={row}/>:<ChildRecords key={child.key} resource={child} parent={resource} parentRow={row} onParentChange={()=>setRevision(v=>v+1)}/>):<Empty title={t('noRelated')} description=" "/>}</div>}
 {tab==='attachments'&&<><div className="attachment-toolbar"><label className="btn primary"><Upload size={16}/>{uploading?t('saving'):t('upload')}<input type="file" hidden disabled={uploading} onChange={e=>{const file=e.target.files?.[0];if(file)void upload(file);}}/></label></div>{attachments.length?<AttachmentList files={attachments}/>:<Empty title={t('noAttachments')} description=" "/>}</>}
 {tab==='activity'&&<HistoryTimeline entries={activity} resourceKey={resource.key}/>}
 {tab==='signatures'&&<>{supportsSignatureRequests(resource)&&<SignatureRequestsPanel resource={resource} row={row}/>} {Boolean(resource.signatureActions?.length)&&<SignatureHistory resource={resource} row={row}/>}</>}
 {assigning&&resources.delegations&&<RecordForm resource={resources.delegations} initial={{target_resource:resource.key,target_id:row.id}} onClose={()=>setAssigning(false)} onSaved={delegation=>{setAssigning(false);setLinked({resource:resources.delegations,row:delegation});}}/>}{linked&&<RecordDetail resource={linked.resource} row={linked.row} onClose={()=>setLinked(null)} onChanged={next=>{setLinked({...linked,row:next});setRevision(v=>v+1);}}/>}{editing&&<RecordForm resource={resource} row={row} onClose={()=>setEditing(false)} onSaved={next=>{setEditing(false);changed(next);}}/>}{action&&(action==='post'&&['expense_claims','vendor_bills','customer_invoices','payments'].includes(resource.key)?<AccountingDialog resource={resource} row={row} onClose={()=>setAction(null)} onSaved={next=>{setAction(null);changed(next);}}/>:<ActionDialog resource={resource} row={row} action={action} onClose={()=>setAction(null)} onSaved={next=>{setAction(null);changed(next);}}/>)}</Modal>;
}

function ChildRecords({resource,parent,parentRow,onParentChange}:{resource:Resource;parent:Resource;parentRow:Row;onParentChange:()=>void}){const {t,label}=useApp();const field=resource.fields.find(f=>f.ref===parent.key);const [rows,setRows]=useState<Row[]>([]);const [error,setError]=useState('');const [editing,setEditing]=useState<Row|'new'|null>(null);const [detail,setDetail]=useState<Row|null>(null);const [revision,setRevision]=useState(0);useEffect(()=>{if(field)api<{rows:Row[]}>(`/api/data/${resource.key}?${field.key}=${parentRow.id}&pageSize=100`).then(data=>setRows(data.rows)).catch(e=>setError(errorMessage(e,t)));},[resource.key,parentRow.id,parentRow.version,revision]);if(!resource.parent&&!rows.length&&!error)return null;return <section className="child-section"><header><h3>{label(resource)} <span className="count">{rows.length}</span></h3>{!resource.readonly&&<Button icon={Plus} onClick={()=>setEditing('new')}>{t('add')}</Button>}</header>{error&&<ErrorBanner message={error}/>}<div className="child-list">{rows.length?rows.map(row=><button key={row.id} onClick={()=>setDetail(row)}><FileText size={16}/><strong>{String(row[resource.titleField]||row.description||row.id.slice(0,8))}</strong>{resource.fields.filter(f=>f.type==='money').map(f=><span key={f.key}>{label(f)}: <DisplayValue field={f} value={row[f.key]} row={row}/></span>)}<ChevronRight size={15}/></button>):<p className="muted compact-empty">{t('noRelated')}</p>}</div>{editing&&<RecordForm resource={resource} row={editing==='new'?undefined:editing} defaults={{currency:parentRow.currency}} initial={field?{[field.key]:parentRow.id}:{}} onClose={()=>setEditing(null)} onSaved={()=>{setEditing(null);setRevision(v=>v+1);onParentChange();}}/>}{detail&&<RecordDetail resource={resource} row={detail} onClose={()=>setDetail(null)} onChanged={next=>{setDetail(next);setRevision(v=>v+1);onParentChange();}}/>}</section>;}

export function ActionDialog({resource,row,action,onClose,onSaved,initialValues}:{resource:Resource;row:Row;action:string;onClose:()=>void;onSaved:(row:Row)=>void;initialValues?:Record<string,unknown>}){
 const {t,label,notify,prefs,me,resources}=useApp();const fields=resource.actionFields?.[action]||[];const signatureRequired=resource.signatureActions?.includes(action)||false;
 const [data,setData]=useState<Record<string,unknown>>(()=>initialValues??(signatureRequired?Object.fromEntries(fields.filter(field=>['time_zone','entry_date'].includes(field.key)).map(field=>[field.key,field.key==='time_zone'?prefs.timezone||'America/Los_Angeles':new Date().toISOString().slice(0,10)])):{time_zone:prefs.timezone||'America/Los_Angeles',entry_date:new Date().toISOString().slice(0,10)}));
 const [actionRow,setActionRow]=useState(row),[busy,setBusy]=useState(false),[error,setError]=useState(''),[key]=useState(()=>crypto.randomUUID());
 const [preview,setPreview]=useState<SignaturePreview|null>(null),[typedName,setTypedName]=useState(''),[consent,setConsent]=useState(false);
 const resetReview=()=>{setPreview(null);setTypedName('');setConsent(false);};
 const canSign=Boolean(preview&&consent&&typedName.trim().normalize('NFC')===me.user.name.trim().normalize('NFC'));
 const submit=async(e:FormEvent)=>{e.preventDefault();if(busy||(signatureRequired&&preview&&!canSign))return;setBusy(true);setError('');try{
  const values={...data,version:actionRow.version,idempotency_key:key};
  if(signatureRequired&&!preview){const reviewed=await post<SignaturePreview>('/api/signatures',{resource:resource.key,record_id:actionRow.id,operation:action,values});if(reviewed.required!==true||!reviewed.reviewed_hash)throw new Error(t('error_signature_invalid'));setPreview(reviewed);setTypedName('');setConsent(false);return;}
  const next=await post<Row>(`/api/data/${resource.key}/${actionRow.id}/actions/${action}`,{...values,...(signatureRequired&&preview?{signature:{typed_name:typedName.trim().normalize('NFC'),consent:true,reviewed_hash:preview.reviewed_hash}}:{})});
  notify(t('success'));const targetId=resource.key==='decisions'&&action==='reconsider'?next.id:actionRow.id;const fresh=await api<Row>(`/api/data/${resource.key}/${targetId}`).catch(()=>next);onSaved(fresh);
 }catch(e){setError(errorMessage(e,t));resetReview();if(signatureRequired){const fresh=await api<Row>(`/api/data/${resource.key}/${actionRow.id}`).catch(()=>null);if(fresh)setActionRow(fresh);}}finally{setBusy(false);}};
 return <Modal title={`${t(resource.key==='delegations'&&action==='revoke'?'delegationRevoke':action)} · ${String(actionRow[resource.titleField]||label(resource))}`} onClose={()=>{if(!busy)onClose();}} footer={<><Button disabled={busy} onClick={onClose}>{t('cancel')}</Button><Button type="submit" form="action-form" variant="primary" disabled={busy||(signatureRequired&&Boolean(preview)&&!canSign)}>{busy?t('saving'):t(signatureRequired?preview?'signatureConfirm':'signatureReviewButton':'confirm')}</Button></>}><form id="action-form" onSubmit={submit}>{error&&<ErrorBanner message={error}/>}<p className="action-description">{label(resource)} · <Badge value={actionRow.status||'active'}/></p>{action==='pay'&&<p className="info-note">{t('paymentNotice')}</p>}{action==='reconsider'&&<p className="info-note">{t('reconsiderHint')}</p>}<fieldset className="action-inputs" disabled={busy}><div className="form-grid single">{fields.filter(field=>action!=='reconsider'||field.key!=='meeting_title'||data.create_meeting===true).map(field=>field.key==='confirmation_note'?<ConfirmationNoteField key={field.key} value={String(data[field.key]??'')} disabled={busy} onChange={value=>{setData(current=>({...current,[field.key]:value}));resetReview();}}/>:<FieldEditor key={field.key} field={field} moneyCurrency={resource.module==='finance'?String(field.key==='payment_amount_minor'?data.payment_currency||actionRow.currency:actionRow.currency||me.company.base_currency):undefined} hint={action==='reconsider'?field.key==='title'?t('reconsiderTitleHint'):field.key==='content'?t('reconsiderContentHint'):field.key==='create_meeting'?t('reconsiderMeetingHint'):undefined:undefined} value={data[field.key]} disabled={busy||(action==='reconsider'&&field.key==='create_meeting'&&resources.meetings?.capabilities?.create!==true)} onChange={value=>{setData(current=>({...current,[field.key]:value}));resetReview();}}/>)}</div>{resource.key==='expense_claims'&&action==='approve'&&<ApprovalLines currency={String(actionRow.currency||me.company.base_currency)} claimId={actionRow.id} onChange={lines=>{resetReview();setData(previous=>{const next={...previous};if(lines.length){next.line_approvals=lines.map(line=>({id:line.id,approved_minor:line.approved_minor}));next.approved_minor=lines.reduce((sum,line)=>sum+BigInt(String(line.approved_minor||0)),0n).toString();}else delete next.line_approvals;return next;});}}/>}</fieldset>{preview&&<SignatureReview preview={preview} resource={resource} typedName={typedName} consent={consent} onName={setTypedName} onConsent={setConsent} disabled={busy}/>}</form></Modal>;
}

function ColumnsDialog({resource,view,onClose,onSave}:{resource:Resource;view:ViewPrefs;onClose:()=>void;onSave:(view:ViewPrefs)=>Promise<void>}){const {t,label}=useApp();const [next,setNext]=useState<ViewPrefs>({columns:view.columns||resource.fields.filter(f=>!['textarea','json'].includes(f.type)).slice(0,6).map(f=>f.key),order:view.order||resource.fields.map(f=>f.key),widths:view.widths||{},...view});const [busy,setBusy]=useState(false);const keys=next.order||resource.fields.map(f=>f.key);const reorder=(index:number,by:number)=>{const copy=[...keys];[copy[index],copy[index+by]]=[copy[index+by],copy[index]];setNext({...next,order:copy});};return <Modal title={t('columns')} onClose={onClose} footer={<><Button onClick={()=>setNext({})}>{t('reset')}</Button><Button variant="primary" disabled={busy} onClick={async()=>{setBusy(true);try{await onSave(next);}finally{setBusy(false);}}}>{t('savedView')}</Button></>}><div className="column-options">{keys.map((key,i)=>{const f=resource.fields.find(item=>item.key===key);if(!f)return null;return <div key={key}><label><input type="checkbox" checked={next.columns?.includes(key)??false} onChange={e=>setNext({...next,columns:e.target.checked?[...(next.columns||[]),key]:(next.columns||[]).filter(k=>k!==key)})}/>{label(f)}</label><input aria-label={`${t('columnWidth')} ${label(f)}`} type="number" min={80} max={600} value={next.widths?.[key]||160} onChange={e=>setNext({...next,widths:{...next.widths,[key]:Math.max(80,Number(e.target.value))}})}/><button className="icon-button" aria-label={t('moveUp')} disabled={i===0} onClick={()=>reorder(i,-1)}><ArrowUp size={15}/></button><button className="icon-button" aria-label={t('moveDown')} disabled={i===keys.length-1} onClick={()=>reorder(i,1)}><ArrowDown size={15}/></button></div>;})}</div></Modal>;}

function Kanban({resource,rows,stages,onOpen,onChange}:{resource:Resource;rows:Row[];stages:Row[];onOpen:(row:Row)=>void;onChange:()=>void}){
 const {t,notify}=useApp();const stageMode=resource.key==='engagements',directMove=resource.key!=='delegations';
 const columns=stageMode?stages.map(s=>({id:s.id,title:String(s.name)})):(resource.states||[]).map(s=>({id:s,title:t(s)}));
 const [moving,setMoving]=useState<string|null>(null),[confirmation,setConfirmation]=useState<{row:Row;action:string}|null>(null);
 const move=async(row:Row,stage:string)=>{
  if(moving||confirmation||String(row[stageMode?'stage_id':'status'])===stage)return;
  const actionMap:Record<string,string>={in_progress:'start',done:'complete',completed:'complete',blocked:'block',cancelled:'cancel',active:'start',on_hold:'pause'},action=actionMap[stage];
  // Board completion follows the same optional-note form and authorization as
  // the record workflow. Moving a card does not submit confirmation immediately.
  if(!stageMode&&action&&recordsConfirmationNote(resource.key,action)){setConfirmation({row,action});return;}
  setMoving(row.id);
  try{
   if(stageMode)await post(`/api/data/${resource.key}/${row.id}/actions/move_stage`,{version:row.version,stage_id:stage,next_step:row.next_step,idempotency_key:crypto.randomUUID()});
   else{if(!action)throw new Error(t('workflow'));await post(`/api/data/${resource.key}/${row.id}/actions/${action}`,{version:row.version,idempotency_key:crypto.randomUUID()});}
   notify(t('success'));onChange();
  }catch(e){notify(errorMessage(e,t),'error');}finally{setMoving(null);}
 };
 return <><div className="kanban">{columns.map(column=><section key={column.id} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const row=rows.find(r=>r.id===e.dataTransfer.getData('text/plain'));if(row&&directMove)void move(row,column.id);}}><header><span>{column.title}</span><b>{rows.filter(r=>String(r[stageMode?'stage_id':'status'])===column.id).length}</b></header>{rows.filter(r=>String(r[stageMode?'stage_id':'status'])===column.id).map(row=><article key={row.id} draggable={directMove&&!moving&&!confirmation} onDragStart={e=>e.dataTransfer.setData('text/plain',row.id)}><button className="kanban-title" onClick={()=>onOpen(row)}>{String(row[resource.titleField])}</button>{row.priority?<Badge value={row.priority}/>:null}<p>{String(row.next_step||row.goal||row.due_date||'').slice(0,120)}</p>{directMove&&<select aria-label={t('move')} value={column.id} disabled={Boolean(moving||confirmation)} onChange={e=>void move(row,e.target.value)}>{columns.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select>}</article>)}</section>)}</div>{confirmation&&<ActionDialog resource={resource} row={confirmation.row} action={confirmation.action} onClose={()=>setConfirmation(null)} onSaved={()=>{setConfirmation(null);onChange();}}/>}</>;
}

function ImportDialog({resource,onClose,onSaved}:{resource:Resource;onClose:()=>void;onSaved:()=>void}){const {t,label,notify}=useApp();const [csv,setCsv]=useState('');const [strategy,setStrategy]=useState('skip');const [preview,setPreview]=useState<Record<string,unknown>|null>(null);const [mapping,setMapping]=useState<Record<string,string>>({});const [error,setError]=useState('');const [busy,setBusy]=useState(false);const headers=csv.split(/\r?\n/)[0]?.split(',').map(s=>s.trim().replace(/^"|"$/g,''))||[];const run=async(commit:boolean)=>{setBusy(true);setError('');try{const result=await post<Record<string,unknown>>('/api/io',{action:commit?'commit':'preview',resource:resource.key,csv,mapping,duplicate_strategy:strategy,preview_id:preview?.id||preview?.preview_id});setPreview(result);if(commit){notify(t('success'));onSaved();}}catch(e){setError(errorMessage(e,t));}finally{setBusy(false);}};return <Modal title={`${t('import')} · ${label(resource)}`} wide onClose={onClose} footer={<><Button onClick={()=>downloadFile(`${resource.key}-template.csv`,resource.fields.filter(f=>!f.readonly).map(f=>f.key).join(',')+'\n','text/csv')}>{t('csvTemplate')}</Button><Button disabled={busy||!csv} onClick={()=>void run(false)}>{t('preview')}</Button><Button variant="primary" disabled={busy||!preview} onClick={()=>void run(true)}>{t('commitImport')}</Button></>}><p className="muted">{t('importHint')}</p>{error&&<ErrorBanner message={error}/>}<label className="btn"><Upload size={16}/>{t('selectFile')}<input type="file" accept=".csv,text/csv" hidden onChange={async e=>{const file=e.target.files?.[0];if(file){setCsv(await file.text());setPreview(null);}}}/></label><textarea className="csv-input" aria-label="CSV" rows={7} value={csv} onChange={e=>{setCsv(e.target.value);setPreview(null);}} placeholder={resource.fields.filter(f=>!f.readonly).map(f=>f.key).slice(0,4).join(',')}/><div className="form-grid">{headers.filter(Boolean).map(header=><div className="field" key={header}><label>{header} → {t('field')}</label><select value={mapping[header]||header} onChange={e=>{setMapping({...mapping,[header]:e.target.value});setPreview(null);}}><option value="">{t('skip')}</option>{resource.fields.filter(f=>!f.readonly).map(f=><option value={f.key} key={f.key}>{label(f)}</option>)}</select></div>)}<div className="field"><label>{t('duplicateStrategy')}</label><select value={strategy} onChange={e=>{setStrategy(e.target.value);setPreview(null);}}>{['skip','reject'].map(s=><option key={s} value={s}>{t(s)}</option>)}</select></div></div>{preview&&<section className="import-preview"><h3>{t('importResult')}</h3><StructuredResult value={preview}/></section>}</Modal>;}
export function StructuredResult({value}:{value:unknown}){const {t,resources,label,locale,prefs}=useApp();function scalar(key:string,v:unknown,record?:Record<string,unknown>){if(isRichText(v))return <RichText value={v}/>;if(v===null||v===undefined||v==='')return '—';if(key.endsWith('_id')&&record){const name=record[key.slice(0,-3)+'_name'];if(typeof name==='string'&&name)return name;}if(key.endsWith('_minor')&&record?.currency)return <DisplayValue field={{key,type:'money',label:[key,key,key]}} value={v} row={record as Row}/>;if(typeof v==='object')return <StructuredResult value={v}/>;if(['resource','source_resource'].includes(key)&&resources[String(v)])return label(resources[String(v)]);if(['status','kind','cycle','operation','direction','scope'].includes(key))return t(String(v));if(key.endsWith('_at')){try{return new Intl.DateTimeFormat(locale,{dateStyle:'medium',timeStyle:'short',timeZone:prefs.timezone||'America/Los_Angeles'}).format(new Date(String(v)));}catch{}}if(key==='code'&&String(v).includes('_'))return t('error_'+String(v).toLowerCase());return String(v);}if(Array.isArray(value)){if(!value.length)return <p className="muted">{t('noData')}</p>;if(typeof value[0]==='object'&&value[0]!==null){const keys=Object.keys(value[0]).filter(k=>!['workspace_id','company_id','created_by','updated_by','id'].includes(k)&&!k.endsWith('_minor_digits')&&!(k.endsWith('_name')&&Object.hasOwn(value[0],k.slice(0,-5)+'_id')));return <div className="table-scroll"><table className="data-table compact"><thead><tr>{keys.map(k=><th key={k}>{fieldName(k)}</th>)}</tr></thead><tbody>{value.map((item,i)=><tr key={i}>{keys.map(k=><td key={k}>{scalar(k,item[k],item)}</td>)}</tr>)}</tbody></table></div>;}return <ul>{value.map((v,i)=><li key={i}>{String(v)}</li>)}</ul>;}if(value&&typeof value==='object')return <div className="structured-result">{Object.entries(value).filter(([key])=>!key.endsWith('_minor_digits')&&!(key.endsWith('_name')&&Object.hasOwn(value,key.slice(0,-5)+'_id'))).map(([key,v])=><div key={key}><h4>{fieldName(key)}</h4>{typeof v==='object'?<StructuredResult value={v}/>:<span>{scalar(key,v,value as Record<string,unknown>)}</span>}</div>)}</div>;return <span>{String(value??'—')}</span>;function fieldName(key:string){const f=Object.values(resources).flatMap(r=>r.fields).find(f=>f.key===key);return moneyLabel(f?label(f):t(key));}}
function DuplicatesHint({resource,data,exclude}:{resource:Resource;data:Record<string,unknown>;exclude?:string}){const {t}=useApp();const [rows,setRows]=useState<Row[]>([]);const [detail,setDetail]=useState<Row|null>(null);const q=String(data.email||data.name||'');useEffect(()=>{if(!['contacts','organizations'].includes(resource.key)||q.length<3)return;let current=true;const timer=setTimeout(()=>{api<{rows:Row[]}>(`/api/data/${resource.key}?q=${encodeURIComponent(q)}&pageSize=20`).then(result=>{if(current)setRows(result.rows.filter(row=>row.id!==exclude));}).catch(()=>{});},400);return()=>{current=false;clearTimeout(timer);};},[resource.key,q,exclude]);if(q.length<3||!rows.length)return null;return <div className="duplicate-hint"><strong>{t('duplicateCandidates')}</strong>{rows.map(row=><button key={row.id} className="text-button" type="button" onClick={()=>setDetail(row)}>{String(row[resource.titleField])} · {String(row.email||'')}</button>)}{detail&&<RecordDetail resource={resource} row={detail} onClose={()=>setDetail(null)} onChanged={setDetail}/>}</div>;}
function ApprovalLines({claimId,currency,onChange}:{claimId:string;currency:string;onChange:(values:Row[])=>void}){const {t}=useApp();const [rows,setRows]=useState<Row[]>([]);const [enabled,setEnabled]=useState(false);const [amounts,setAmounts]=useState<Record<string,string>>({});useEffect(()=>{api<{rows:Row[]}>(`/api/data/expense_lines?claim_id=${claimId}&pageSize=200`).then(result=>{setRows(result.rows);setAmounts(Object.fromEntries(result.rows.map(r=>[r.id,(BigInt(String(r.amount_minor||0))+BigInt(String(r.tax_minor||0))).toString()])));}).catch(()=>{});},[claimId]);const change=(next:Record<string,string>)=>{setAmounts(next);onChange(rows.map(row=>({...row,approved_minor:next[row.id]||'0'})));};return <div className="approval-lines"><label className="check-line"><input type="checkbox" checked={enabled} onChange={e=>{setEnabled(e.target.checked);onChange(e.target.checked?rows.map(row=>({...row,approved_minor:amounts[row.id]||'0'})):[]);}}/>{t('lineApproval')}</label>{enabled&&<div className="table-scroll"><table className="data-table compact"><thead><tr><th>{t('notes')}</th><th>{t('amount')}</th><th>{t('approvedAmount')}</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td>{String(row.description)}</td><td><DisplayValue field={{key:'amount_minor',label:['','',''],type:'money'}} value={(BigInt(String(row.amount_minor||0))+BigInt(String(row.tax_minor||0))).toString()} row={{...row,currency}}/></td><td><MoneyInput aria-label={`${t('approvedAmount')} ${String(row.description)}`} value={amounts[row.id]||'0'} currency={currency} onValue={value=>change({...amounts,[row.id]:value})}/></td></tr>)}</tbody></table></div>}</div>;}










function ContextRecords({groups}:{groups:{resource:string;rows:Row[];total:number}[]}){
 const {resources,label,t,navigate}=useApp();const [detail,setDetail]=useState<{resource:Resource;row:Row}|null>(null);
 return <>{groups.filter(group=>resources[group.resource]).map(group=>{const resource=resources[group.resource];return <section className="child-section" key={group.resource}><header><h3>{t('contextRecords')} · {label(resource)} <span className="count">{group.total}</span></h3></header>{group.total>group.rows.length&&<p className="muted small">{t('contextLimit')} <Button onClick={()=>navigate(`/data/${group.resource}`)}>{t('viewAll')}</Button></p>}<div className="child-list">{group.rows.map(row=><button key={row.id} onClick={()=>setDetail({resource,row})}><FileText size={16}/><strong>{String(row[resource.titleField]||row.id.slice(0,8))}</strong>{row.status?<Badge value={row.status}/>:null}<ChevronRight size={15}/></button>)}</div></section>;})}{detail&&<RecordDetail resource={detail.resource} row={detail.row} onClose={()=>setDetail(null)} onChanged={row=>setDetail({...detail,row})}/>}</>;
}
